"""Build a compact, English report from the measured synthetic RTX 3090 runs."""
import json,statistics,html
from pathlib import Path
ROOT=Path(__file__).resolve().parent

def lines(name):
 out=[]
 for line in (ROOT/'logs'/name).read_text().splitlines():
  try:out.append(json.loads(line))
  except (ValueError,TypeError):pass
 return out
before=lines('rtx3090-tts-before.jsonl')[0];after=lines('rtx3090-tts-after.jsonl')[0]
quality=json.loads((ROOT/'static/rtx3090-quality.json').read_text())
mic=lines('rtx3090-mouth-to-ear-final.jsonl')
keys=['mouth_to_ear_ms','speech_end_to_asr_text_ms','server_first_audio_ms','server_llm_first_sentence_ms','server_tts_first_audio_ms','browser_start_buffer_ms']
summary={k:statistics.median([r[k] for r in mic if k in r]) for k in keys if any(k in r for r in mic)}
flags=dict(line.split('=',1) for line in (ROOT/'optimizations/rtx3090-speed.env').read_text().splitlines() if line and not line.startswith('#'))
report={'hardware':'Two RTX 3090 24 GiB; TTS on GPU 1; other resident services remain loaded.','versions':'torch 2.6.0+cu124, Triton 3.2.0','checkpoint':'laion/Humaneness-Voice-Small-1.1-Alpha-RL-r128-v1, revision 182bc700','source':'LAION-AI/Humaneness-Voice d3d1045; local zero-temperature sampler guard','before':before,'after':after,'flags':flags,'quality':quality,'browser_rows':mic,'browser_medians_ms':summary,'scope':'Warm local TTS runs (three seeds per condition); synthetic browser microphone through HTTPS (three requests), no physical mic or device latency. Different seeds/numerics can produce different durations.','codec_correctness':'On three fixed seeds, BF16 waveforms were bit-identical with and without codec graphs. Reference copy cache: 262.9 ms initial encode, 0.6 ms on subsequent copies.','limitations':'BF16 and different sampling random streams can change outputs. Four zero-WER fixtures are not a comprehensive naturalness or speaker-identity evaluation. One cold-load compiled sampler failed on torch 2.6, so its flag is off; Triton local decode is enabled. First PCM can contain leading silence: in three positive-temperature quality probes the first nonquiet chunk arrived at approximately 127–139 ms. Browser results exclude physical device latency. Preliminary mouth-to-ear values counted an internal pause as speech end and are superseded by the final runs.'}
(ROOT/'static/rtx3090-speed.json').write_text(json.dumps(report,indent=2,ensure_ascii=False))
rows=''
for label,key in [('First PCM packet, seconds','first_pcm_s'),('Full audio generation, seconds','total_s'),('Generated duration, seconds','audio_s'),('Simulated playback gaps, seconds','gap_s')]:rows+=f'<tr><td>{label}</td><td>{before[key]}</td><td>{after[key]}</td></tr>'
for label,r in [('RTF (generation/audio; lower is faster)',None)]:rows+=f'<tr><td>{label}</td><td>{before["total_s"]/before["audio_s"]:.3f}</td><td>{after["total_s"]/after["audio_s"]:.3f}</td></tr>'
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Robby RTX 3090 speed results</title><style>body{font:17px/1.6 system-ui;max-width:1050px;margin:32px auto;padding:20px;color:#21333b;background:#faf9f6}table{border-collapse:collapse;width:100%}td,th{border:1px solid #c4cdd0;padding:10px;text-align:left}pre{white-space:pre-wrap;overflow-wrap:anywhere}a{color:#066a83}</style><h1>Robby: RTX 3090 inference optimizations</h1><p>Measured 3 November 2026. Warm synthetic tests on this machine; these numbers do not describe the Jetson Thor used in the upstream guide.</p><table><tr><th>TTS measurement (median of three)</th><th>Before</th><th>Optimized</th></tr>'''+rows+'''</table><p>First PCM measures packet arrival, including any initial silence. The separate quality probes received their first nonquiet chunk after roughly 127–139 ms. The benchmark uses the same text, voice, temperature and guidance; the optimized sampler/precision can change sampled tokens and durations.</p><h2>What changed</h2><p>BF16 merged policy weights, content-hashed reference caching, early streaming release with a final cutoff, a 3→6→12→20-frame chunk ramp, semantic CUDA graphs with compiled decode, codec CUDA graphs and fused Triton kernels, and the Triton local codebook decoder. The torch.compile local sampler failed with the installed older PyTorch and is disabled; the published Triton path runs instead. Temperature zero has an explicit greedy fallback. Model warm-up is required after restart.</p><h2>End to end</h2><p>Real Chrome with a synthetic microphone, through the existing HTTPS demo. Timing runs from the final audible microphone block to scheduled browser output; excludes the physical device. No baseline whole-pipeline comparison was made in this session. The final microphone test uses the last audible block because the authored wake phrase can contain a long internal pause.</p><pre>'''+html.escape(json.dumps(summary,indent=2))+'''</pre><h2>Quality and limits</h2><p>Four authored German fixtures, including expressive prompts and temperature zero, produced finite audible PCM and zero Parakeet WER. Codec graphs reproduced bit-identical BF16 waveforms on three fixed seeds. This does not establish unchanged subjective naturalness or speaker similarity across arbitrary inputs. The browser start reserve stays around 300 ms for small first chunks; smaller reserves previously caused jitter. Background load and cloud LLM latency vary.</p><h2>Reproduce</h2><p>See RTX3090_OPTIMIZATIONS.md and the upstream INFERENCE_OPTIMIZATIONS.md. Use rtx3090-speed.env with the pinned upstream TTS runtime and the zero-temperature patch. Run live_latency_benchmark.py serially, then rtx3090_quality_check.py and browser_mouth_to_ear.py. Never run the separate engine benchmark concurrently with a latency measurement.</p><h2>Recorded configuration and measurements</h2><pre>'''+html.escape(json.dumps(report,indent=2,ensure_ascii=False))+'''</pre><p><a href="/desk-robot/">Return to Robby</a></p></html>'''
(ROOT/'static/rtx3090-speed.html').write_text(page)
print(json.dumps(summary))
